const CLASSIC_TOOLBAR_LAYOUT = 0x21000016;
/** gmToolbarUI::HandleSelectionChanged @ 004bf380 — the selected-object field's states. */
const TOOLBAR_SEL_STATE_SINGLE = 0x1000000b;
const TOOLBAR_SEL_STATE_STACK = 0x1000000c;

