/**
 * GAP.world-drag-drop — what a drag released over the 3D view carries: an
 * inventory cell (index into the inventory list), a paperdoll slot, or an
 * object dragged off the world itself.
 */
export type WorldDropSource =
  | { kind: 'inventory'; itemIndex: number }
  | { kind: 'equipped'; slot: EquipMask }
  | { kind: 'world'; guid: number };

/**
 * SWEEP1006B placement — where a drag was released on the inventory's item
 * lists (UIElement_ItemList::AcceptDragObject @ 004e4250): a cell of the
 * item grid showing pack `packSlot` (cellItemId 0 = an empty cell), or a
 * slot of the pack column (0 = the main pack / player, 1-7 side packs).
 */
export type ItemListDropTarget =
  | { list: 'items'; packSlot: number; cellItemId: number; cellIndex?: number }
  | { list: 'packs'; packSlot: number };

/**
 * RECON.inventory-grid-dat-cells.b.a — UIElement_ItemList::m_pendingItem of
 * the inventory's item list (gmInventoryUI +0x600): an object on its way into
 * the shown pack, drawn at `index` with the waiting ghost 0x10000349 until
 * the server answers. Put there by gmInventoryUI::RecvNotice_ShowPendingInPlayer
 * @ 004a6b50 (PlaceInBackpack: index 0) and UIElement_ItemList::AcceptDragObject
 * @ 004e4250 (the drop's cell); ItemList_InsertItem @ 004e3f40 opens the cell.
 */
export interface PendingPackItem {
  guid: number;
  /** The pack the item list showed (0 = main pack, 1-7 side packs). */
  packSlot: number;
  index: number;
  iconDid: number;
  iconOverlayDid?: number;
  iconUnderlayDid?: number;
  itemType?: number;
  uiEffects?: number;
  /** GetObjectNameWide(itemID, 2) — for AcceptDragObject's "Already attempting to place %s here". */
  name?: string;
}

/**
 * RECON.inventory-grid-dat-cells.b.a.a — UIElement_ItemList::AcceptDragObject
 * @ 004e4250: a drop on an item list that still shows a pending item is
 * refused with this 0x1a line (.rdata 0x7bfd40, %s = the pending item's
 * GetObjectNameWide(id, 2)) — the second drop waits for the first answer.
 */
export function alreadyPlacingText(name: string): string {
  return `Already attempting to place ${name} here`;
}

/** GameEventStartBarber / GameActionFinishBarber's 16 fields (GAP.barber-ui-retail: BarberModel.ts). */
