/**
 * Minimal interface for syncing PlayerState → UI without importing the full class.
 * Matches the public API of packages/renderer/src/player/PlayerState.ts.
 */
export interface PlayerStateLike {
  name: string;
  heritage: number;
  gender: number;
  level: number;
  totalBurden: number;
  xp: {
    totalXp: bigint; availableXp: bigint; availableSkillCredits: number;
    /** GAP.14 — XpSystem methods; panel math delegates to these (single source). */
    xpToNextLevel?(levelXpTable: bigint[]): bigint;
    getProgressToNextLevel?(levelXpTable: bigint[]): number;
  };
  health: { current: number; max: number };
  stamina: { current: number; max: number };
  mana: { current: number; max: number };
  /** CORE.7 — VitalSystem raise counts (VitalId 1/2/3) for the
   *  select-to-raise footer's vital costs. Optional so existing test fakes
   *  that pre-date this interface don't have to be touched. */
  vitals?: { getRaises(id: number): number };
  attributes: { getCurrent(id: number): number };
  /** STATS.enchantments-never-populated — ACE CreatureAttribute.Current (the
   *  BUFFED value). Optional so older test fakes stay valid; absent ⇒ base. */
  getAttributeCurrent?(id: number): number;
  /** ACE CreatureSkill.Current (buffed) / .Base (unbuffed, with aug base
   *  bonuses). Optional; absent ⇒ skills.getTotal for both. */
  getSkillCurrent?(id: number, skillTable: Map<number, SkillBase>): number;
  getSkillBase?(id: number, skillTable: Map<number, SkillBase>): number;
  skills: {
    getAllSkillIds(): number[];
    getAdvancementClass(id: number): number;
    getRaises(id: number): number;
    /** RECON.skill-raise-ignores-pp — Skill::_pp; optional for older fakes. */
    getExperienceSpent?(id: number): number | undefined;
    /** FAITHFUL.590 — effective skill value per ACE CreatureSkill.Current
     *  (attribute formula + InitLevel + Ranks). Optional so existing test
     *  fakes that pre-date this interface don't have to be touched; when
     *  absent the panel falls back to the raises count. */
    getTotal?(id: number, skillTable: Map<number, SkillBase>, attributes: { getCurrent(id: number): number }): number;
  };
  /** FAITHFUL.255 — used to drive the vitae HUD indicator. Optional so
   *  existing test fakes that pre-date this interface don't have to be touched. */
  vitae?: { vitaePenalty: number };
  /** CORE.6.b — PropertyInt64.AvailableLuminance (6) / MaximumLuminance (7)
   *  for the stat-pane luminance rows 0x100005c5/0x100005c6. Optional so
   *  existing test fakes that pre-date this interface don't have to be touched. */
  availableLuminance?: bigint;
  maximumLuminance?: bigint;
}

