/* ------------------------------------------------------------------ */
/*  GameUI                                                             */
/* ------------------------------------------------------------------ */

/**
 * VISUAL.preworld-hover-tooltips — the chargen element under the mouse
 * that carries a tooltip (UIElementManager hit-tests the element tree by
 * rectangle). DOM hit-testing alone misses the DAT tabs: the layout
 * renders them pointer-events:none under the clickable tab bar, so the
 * event target is the bar. Take the nearest tagged ancestor of the target,
 * else the deepest (last in document order) visible tagged element whose
 * rectangle holds the point.
 */
export function chargenTooltipTargetAt(root: HTMLElement, target: Element | null, x: number, y: number): HTMLElement | null {
  const own = target?.closest?.('[data-ac-tooltip]') as HTMLElement | null | undefined;
  if (own && root.contains(own)) return own;
  let best: HTMLElement | null = null;
  for (const el of root.querySelectorAll<HTMLElement>('[data-ac-tooltip]')) {
    if (!el.dataset.acTooltip) continue;
    const r = el.getBoundingClientRect();
    if (r.width <= 0 || r.height <= 0) continue;
    if (x >= r.left && x < r.right && y >= r.top && y < r.bottom) best = el;
  }
  return best;
}

/** The CharGenVerificationResponse NameBanned text FINISH shows for a name the DAT name rules refuse. */
export const CHARGEN_NAME_REFUSED_TOKEN = 'ID_Character_Err_NameBanned';

/**
 * BUG.chargen-finish-silent — how long FINISH waits for the
 * CharGenVerificationResponse before giving up (retail had no timer: its
 * server always answered; ACE answers nothing when its handler throws).
 * A create normally answers in well under a second.
 */
export const CHARGEN_REPLY_TIMEOUT_MS = 20_000;

/** The Please Wait box Create Character raises while the streamed world art is still loading. */
export const CHARGEN_WORLD_ART_WAIT_ID = 'chargen-pleasewait';

/**
 * BUG.stale-wait-plate-modal (2026-10-14) — an element is on screen: in the
 * document and neither it nor any ancestor is display:none / [hidden].
 * `isConnected` plus the element's own style.display is not enough: a dialog
 * left inside a hidden screen container (char select's Entering World plate
 * after the world starts) stays connected with display intact. Browsers
 * answer with checkVisibility() (it also sees stylesheet rules); elsewhere
 * (happy-dom) the ancestor walk reads computed display.
 */
export function isElementDisplayed(el: HTMLElement | null | undefined): boolean {
  if (!el || !el.isConnected) return false;
  const check = (el as HTMLElement & { checkVisibility?: () => boolean }).checkVisibility;
  if (typeof check === 'function') return check.call(el);
  for (let n: HTMLElement | null = el; n; n = n.parentElement) {
    if (n.hidden || n.style.display === 'none') return false;
    if (typeof getComputedStyle === 'function' && getComputedStyle(n).display === 'none') return false;
  }
  return true;
}

