  private chargenAnimPinned = false;

  /**
   * Capture tooling: restart the chargen 3D views' idle animation at frame 0
   * and hold it there (dt 0), so screen-regression captures of the
   * Appearance/Summary pages match between runs. Their figure plays a 30 fps
   * loop (gmCG3DView::StartAnimation), so each capture caught a different
   * frame (0.7% / 6,800-px diffs on identical code). Gameplay never calls it.
   */
  pinChargenAnimation(pinned = true): void {
    this.chargenAnimPinned = pinned;
    if (!pinned) return;
    for (const a of [this.chargenViewAnimator, this.chargenSummaryAnimator]) if (a?.currentMode === 'idle') a.start();
    if (this.screenContainer.querySelector('.chargen-preview-canvas')) this.renderChargenPreview(false);
    else if (this.screenContainer.querySelector('.chargen-summary-canvas')) this.renderChargenSummaryView(false);
  }
  /**
   * Capture tooling: hold every edit field's caret lit instead of blinking
   * (DatEditField.pinCaretBlink), so a capture of a focused field — the
   * chargen summary's name opens focused — matches between runs.
   * Gameplay never calls it.
   */
  pinCaretBlink(pinned = true): void { pinCaretBlink(pinned); }
  private chargenSummaryObject: SummaryViewObject | null = null;
