  /**
   * NO-DEAD-ENDS for older worlds (docs/ac1999-support-scope.md Phase 5):
   * the features this world's era lacks (era/EraFeatures.ts). Their controls
   * are not built — toolbar buttons, panels, tabs, option rows, menu items,
   * Keyboard Config commands. Empty (end of retail, classic eras): nothing
   * changes.
   */
  private eraUnsupported: ReadonlySet<EraFeature> = new Set();

  /** Set once per page load from the era profile, before the HUD is shown. */
  setUnsupportedFeatures(features: ReadonlySet<EraFeature>): void {
    this.eraUnsupported = features;
    if (!this.eraSupports('characterTitles') && this.charPanelTab === 'titles') this.charPanelTab = 'attributes';
    if (this.socialTabHidden(this.socialTab)) this.socialTab = 'fellowship';
  }

  /** Whether this world's era lacks the Social panel tab `tab` (FEATURE_SOCIAL_TABS). */
  private socialTabHidden(tab: string): boolean {
    return hiddenBy(FEATURE_SOCIAL_TABS, this.eraUnsupported).has(tab);
  }

  /** Whether this world's era has `feature`. */
  eraSupports(feature: EraFeature): boolean {
    return !this.eraUnsupported.has(feature);
  }

  /**
   * AC1999.spell-research-panel — whether the magic panel has the 1999
   * "Create Spell" tab (eraClientRules().spellResearch; SpellResearch1999.ts).
   * Set once per page load from the era profile, like setUnsupportedFeatures.
   */
