  keybindRegistry: KeybindRegistry | null = null;

  /**
   * BUG.tab-toggles-combat — whether a key pressed in the chat bar is the
   * current Enter/Exit Chat Mode binding (0x10000024; retail default Tab).
   * Its input map 0x1000000d is co-active with every other map, so the check
   * is map-agnostic. With no registry wired the retail default applies.
   */
  private isEnterExitChatModeKey(e: KeyboardEvent): boolean {
    const reg = this.keybindRegistry;
    if (!reg) return e.key === 'Tab' && !e.ctrlKey && !e.altKey && !e.shiftKey && !e.metaKey;
    return reg.getMappings(ACT.EnterExitChatMode).includes(eventToCode(e));
  }
