      0x060019f2, 0x060019f3, 0x060019f4, 0x060019f5, // filled corner numerals 1-9
      0x06001acc, 0x06001acd, 0x06001ace, 0x06001acf, 0x06001ad0,
      0x06001ad1, 0x06001ad2, 0x06001ad3, 0x06001ad4, // ghosted corner numerals 1-9
      // RECON.inventory-grid-dat-cells — the pack / paperdoll UIItem's own
      // 0x1000034a tag table (overlays 0x21000037:0x10000346, prop 0x10000042).
      0x0600109e, 0x0600109f, 0x060010a0, 0x060010a1, 0x060010a2,
      0x060010a3, 0x060010a4, 0x060010a5, 0x060010a6, // pack shortcut tags 1-9
      0x060074d3, 0x060074d2, // blank tag (slots 10-18), normal / ghosted
      ITEM_WAITING_GHOST_MEDIA, // RECON.inventory-grid-dat-cells.b — waiting ghost 0x10000349 (0x0600109a)
      ITEM_SELL_STATE_MEDIA, // RECON.inventory-grid-dat-cells.c — sell-state badge 0x10000437 (0x060012d9)
